#!/usr/bin/env python3
"""Idempotently add the Joel 2:28–29 expansion to ot/joel/ch02.html."""
from __future__ import annotations

import argparse
import base64
import gzip
from collections import Counter
from html.parser import HTMLParser
from pathlib import Path

FRAGMENT_GZIP_B64 = """"""
NEW_IDS = ("v28c", "v28d", "v28e", "v28f", "v29b", "v29c", "v29d", "v29e", "v29f", "v29g")
MARKER = '    <div class="back"><a href="#top">↑ 처음으로</a></div>\n  </section>\n\n  <!-- ═══════ 10 ═══════ -->'

class IdParser(HTMLParser):
    def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self.ids: list[str] = []
        self.hrefs: list[str] = []

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        data = dict(attrs)
        if data.get("id"):
            self.ids.append(data["id"] or "")
        if tag == "a" and data.get("href"):
            self.hrefs.append(data["href"] or "")

def validate(text: str) -> None:
    parser = IdParser()
    parser.feed(text)
    parser.close()
    counts = Counter(parser.ids)
    duplicates = sorted(key for key, value in counts.items() if value > 1)
    if duplicates:
        raise SystemExit(f"duplicate HTML ids: {duplicates}")
    missing = [item for item in NEW_IDS if item not in counts]
    if missing:
        raise SystemExit(f"missing expansion ids: {missing}")
    broken = sorted({href for href in parser.hrefs if href.startswith('#') and href != '#' and href[1:] not in counts})
    if broken:
        raise SystemExit(f"broken fragment anchors: {broken}")
    if text.count('표 5-1.') != 1 or text.count('표 5-5.') != 1:
        raise SystemExit("supplementary table numbering is incomplete")

def apply(repo: Path, write: bool) -> bool:
    target = repo / "ot" / "joel" / "ch02.html"
    text = target.read_text(encoding="utf-8")
    fragment = gzip.decompress(base64.b64decode(FRAGMENT_GZIP_B64)).decode("utf-8")
    present = [item in text for item in NEW_IDS]
    if all(present):
        validate(text)
        print("Joel 2 spirit expansion already present")
        return False
    if any(present):
        raise SystemExit("partial Joel 2 expansion detected; refusing to duplicate content")
    if text.count(MARKER) != 1:
        raise SystemExit("could not resolve the unique insertion marker in Joel 2 section 9")
    updated = text.replace(MARKER, fragment + "\n\n" + MARKER, 1)
    validate(updated)
    if write:
        target.write_text(updated, encoding="utf-8")
        print(f"updated {target}")
    else:
        print("Joel 2 spirit expansion needs to be applied")
    return True

def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo", type=Path, default=Path("."))
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--write", action="store_true")
    mode.add_argument("--check", action="store_true")
    args = parser.parse_args()
    changed = apply(args.repo.resolve(), args.write)
    return 1 if args.check and changed else 0

if __name__ == "__main__":
    raise SystemExit(main())
